const config=window.OWAYS;const $=s=>document.querySelector(s);const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('#subscriptions-grid').innerHTML=config.subscriptions.map((p,i)=>`<article class="product ${i===0?'featured':''}">${i===0?'<span class="product-badge">للإنتاجية والإبداع</span>':''}<div class="product-icon" style="background:${p.color}">${safe(p.icon)}</div><h3 dir="ltr">${safe(p.name)}</h3><p>${safe(p.desc)}</p><div class="price">${p.price===null?'حسب الخطة':safe(p.price)+' '+safe(config.currency)}<small>تفاصيل السعر عند الطلب</small></div><ul>${p.features.map(f=>`<li>${safe(f)}</li>`).join('')}</ul><button class="button" data-add="${p.id}">طلب الاشتراك <span>＋</span></button></article>`).join('');
$('#web-grid').innerHTML=config.web.map((p,i)=>`<article class="web-card"><div class="web-preview"><div class="browser-dots">● ● ●</div><div class="mock-body"><div style="${i===1?'flex:2':i===2?'background:linear-gradient(90deg,#59baff44 30%,transparent 30%,transparent 35%,#59baff44 35%,#59baff44 65%,transparent 65%,transparent 70%,#59baff44 70%)':''}"></div><span><i></i><i></i><i></i></span></div></div><h3>${safe(p.name)}</h3><p>${safe(p.desc)}</p><ul>${p.features.map(f=>`<li>${safe(f)}</li>`).join('')}</ul><button class="button outline" data-add="${p.id}">اطلب عرض سعر ←</button></article>`).join('');
let cart=[];try{const saved=JSON.parse(localStorage.getItem('oways-cart')||'[]');if(Array.isArray(saved))cart=saved.filter(id=>[...config.subscriptions,...config.web].some(p=>p.id===id));}catch{}function refresh(){const items=cart.map(id=>[...config.subscriptions,...config.web].find(p=>p.id===id));$('#count').textContent=items.length;$('#cart-items').innerHTML=items.length?items.map(p=>`<div class="cart-item"><div>${safe(p.name)}<small>${p.price!=null?safe(p.price)+' '+safe(config.currency):'السعر يُحدَّد بعد مراجعة الطلب'}</small></div><button data-remove="${p.id}" aria-label="حذف ${safe(p.name)}">حذف</button></div>`).join(''):'<p>سلتك فارغة. اكتشف الخدمات وأضف ما يناسبك.</p>';$('#checkout').disabled=!items.length;$('#total').textContent=items.length?'تُؤكَّد التكلفة النهائية قبل الشراء.':'';try{localStorage.setItem('oways-cart',JSON.stringify(cart))}catch{}}refresh();let timer;function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',2500)}
function contact(msg){if(/^\d{8,15}$/.test(config.whatsapp)){window.open('https://wa.me/'+config.whatsapp+'?text='+encodeURIComponent(msg),'_blank','noopener,noreferrer')}else{$('#message').value=msg;$('#copy-status').textContent='';$('#contact').showModal()}}
document.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add){if(!cart.includes(add.dataset.add)){cart.push(add.dataset.add);refresh();toast('أُضيفت الخدمة إلى السلة')}else toast('الخدمة موجودة في السلة')}const remove=e.target.closest('[data-remove]');if(remove){cart=cart.filter(id=>id!==remove.dataset.remove);refresh()}const close=e.target.closest('[data-close]');if(close)closeDialog($('#'+close.dataset.close));const c=e.target.closest('[data-contact]');if(c)contact(c.dataset.contact)});$('.cart-toggle').onclick=()=>$('#cart').showModal();$('#menu').onclick=()=>{const open=!$('#navigation').classList.contains('open');if(open){$('#navigation').classList.remove('closing');$('#navigation').classList.add('open')}else closeMenu();$('#menu').setAttribute('aria-expanded',open)};document.querySelectorAll('nav a').forEach(a=>a.onclick=()=>{closeMenu();$('#menu').setAttribute('aria-expanded','false')});$('#checkout').onclick=()=>{closeDialog($('#cart'));contact('مرحبًا أويس تك، أرغب في طلب الخدمات التالية:\n'+cart.map(id=>[...config.subscriptions,...config.web].find(p=>p.id===id).name).join('\n')+'\nيرجى إرسال الأسعار والمدة وتفاصيل التفعيل والتنفيذ.')};$('#renew-form').onsubmit=e=>{e.preventDefault();if(!$('#reference').value.trim())return;contact('أرغب في تجديد اشتراك '+$('#service').value+'\nبيانات الطلب السابق: '+$('#reference').value.trim())};$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText($('#message').value);$('#copy-status').textContent='تم نسخ الرسالة.'}catch{$('#message').select();$('#copy-status').textContent='حدّد النص وانسخه يدويًا.'}};$('#year').textContent=new Date().getFullYear();document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d)}}));

// Shared motion: respect the visitor's reduced-motion preference.
const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
function closeDialog(dialog){if(dialog.classList.contains('closing'))return;if(reducedMotion.matches){dialog.close();return}dialog.classList.add('closing');setTimeout(()=>{dialog.classList.remove('closing');dialog.close()},180)}
function closeMenu(){const nav=$('#navigation');if(reducedMotion.matches){nav.classList.remove('open');return}nav.classList.add('closing');nav.classList.remove('open');setTimeout(()=>nav.classList.remove('closing'),180)}
document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('cancel',event=>{event.preventDefault();closeDialog(dialog)}));
if('IntersectionObserver' in window){const revealObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');revealObserver.unobserve(entry.target)}})},{threshold:.08});document.querySelectorAll('.section-head,.product,.split-panel,.web-card,.ads-panel,.renew-copy,#renew-form,.center,.benefits article,.support').forEach((el,i)=>{el.classList.add('reveal');el.style.setProperty('--reveal-delay',((i%3)*60)+'ms');revealObserver.observe(el)});
const sectionObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting)document.querySelectorAll('nav a').forEach(a=>{const active=a.getAttribute('href')==='#'+entry.target.id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})})},{rootMargin:'-15% 0px -60% 0px',threshold:0});document.querySelectorAll('main section[id]').forEach(section=>sectionObserver.observe(section))}
document.addEventListener('click',event=>{if(event.target.closest('[data-add]')){const cartButton=$('.cart-toggle');cartButton.classList.remove('pulse');void cartButton.offsetWidth;cartButton.classList.add('pulse')}});
